-- person directory extract
SELECT DISTINCT *, p.*, p.record_id, p.first_name AS given_name, U&"given_name", _latin1"last_name", p.last_name, p.first_name || ' ' || p.last_name AS full_name, ARRAY[p.record_id::text], ARRAY(SELECT record_id FROM occupation), MULTISET[p.record_id], MULTISET(SELECT record_id FROM occupation), TABLE(SELECT record_id FROM occupation), MULTISET[p.record_id] MULTISET UNION ALL MULTISET[1], SET(MULTISET[p.record_id]), CARDINALITY(ARRAY[p.record_id]), ELEMENT(MULTISET[p.record_id]), ABSENT ON NULL, p.notes->'city'->>'name', p.age, p.eye_color, p.email, p.phone_number, public.person.status, count(*) FILTER (WHERE p.age > 17), GROUPING(p.record_id), rank() OVER (PARTITION BY p.age ORDER BY p.record_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW EXCLUDE NO OTHERS), lag(p.record_id, 1) IGNORE NULLS OVER w, sum(rank() OVER (ORDER BY p.record_id)) OVER (PARTITION BY p.age), GROUPING(p.record_id, p.age), LOCALTIME, LOCALTIMESTAMP(6), CURRENT_ROLE, CURRENT_SCHEMA, true AS is_active, false AS is_cycle, UPPER(p.last_name), LOWER(p.first_name), CHAR_LENGTH(p.last_name), OVERLAY(p.last_name PLACING 'X' FROM 1 FOR 1), NORMALIZE(p.first_name), FLOOR(o.salary), POWER(o.salary, 2), WIDTH_BUCKET(o.salary, 0, 100, 10), NULLIF(o.job_title, U&'none') AS null_title, coalesce(o.job_title, U&'none') AS title, CASE /* age band */ WHEN p.age < 18 THEN 'minor' WHEN p.age >= 65 THEN 'senior' ELSE 'adult' END AS age_group, a.city, a.province, a.country, a.postal_code, o.department, o.salary, CAST(o.salary AS numeric), TREAT(o.salary AS numeric), PERIOD (p.sys_start, p.sys_end) CONTAINS PERIOD (p.sys_start, p.sys_end), XMLPARSE ( DOCUMENT '<a/>' ), JSON_VALUE ( p.notes , '$.city' ), p.notes[0].name, p.notes IS JSON OBJECT, MDARRAY [ 0 : 1 ] ( 1 , 2 ), MDARRAY_SUM ( p.record_id ), p.notes [ 0 : 1 , * ], DEREF(p.manager), REF(p), p.manager->name, SPECIFICTYPE(p), p.label(), (p AS sch.person).label(), sch.person::make(p.first_name), NEW sch.person(p.first_name), NEXT VALUE FOR public.record_id_seq, o.salary::numeric(10, 2), CAST(o.salary AS integer), CAST(o.salary AS float), CAST(p.first_name AS character large object), CAST(p.first_name AS national character varying(10)), CAST(p.notes AS binary large object), CAST(p.notes AS xml), CAST(p.notes AS json), CAST(ARRAY[p.record_id] AS integer array), CAST(ARRAY[p.record_id] AS integer multiset), CAST(p.record_id AS row(id integer)), CAST(p.record_id AS ref(person)), CAST(p.record_id AS public.person_id), CAST(p.record_id AS integer mdarray[5]), o.salary * 1.1e0 AS raised, (WITH RECURSIVE LINEAR org (id) AS (SELECT 1 UNION ALL SELECT 1) SEARCH DEPTH FIRST BY id SET seq CYCLE id SET is_cycle TO TRUE DEFAULT FALSE USING path SELECT 1), (SELECT max(salary) FROM occupation) AS cap INTO ?, :out_id FROM public.person FOR SYSTEM_TIME AS OF DATE '2011-01-01' MATCH_RECOGNIZE ( PATTERN ( a ) DEFINE a AS record_id > 0 ) AS p TABLESAMPLE BERNOULLI (10) REPEATABLE (1) INNER JOIN public.address AS a ON p.address_id = a.address_id LEFT JOIN occupation AS o ON p.occupation_id = o.occupation_id RIGHT OUTER JOIN department AS d ON o.department_id = d.department_id FULL JOIN region AS r ON a.region_id = r.region_id JOIN country AS c ON a.country_id = c.country_id CROSS JOIN UNNEST(ARRAY[p.record_id]) WITH ORDINALITY AS ids (id, n) CROSS JOIN calendar AS cal NATURAL LEFT JOIN status_flag NATURAL JOIN audit INNER JOIN extra USING (record_id, tenant_id) JOIN (SELECT record_id FROM watchlist) AS w ON p.record_id = w.record_id , LATERAL (SELECT 1) AS lat (n), ONLY (public.person) AS op, TABLE(ARRAY[1]) AS tf (id), gen(1) AS fn, (VALUES (1, 2)) AS vals (a, b) WHERE p.record_id != ? AND p.age = :min_age AND p.age BETWEEN 18 AND 65 AND p.age NOT BETWEEN 0 AND 1 AND p.eye_color IN ('blue', 'green', 'hazel', 'brown') AND p.status = 'active' AND p.last_name LIKE 'S%' AND p.last_name SIMILAR TO 'S%' ESCAPE '/' AND p.record_id IS DISTINCT FROM 1 AND p.record_id IS NOT DISTINCT FROM p.record_id AND p.first_name IS NORMALIZED AND p.first_name IS NOT NFC NORMALIZED AND p.email NOT LIKE '%test%' AND a.country = 'Canada' AND p.age > 17 AND p.age >= 18 AND p.age < 66 AND p.age <= 65 AND p.record_id <> 1 AND NOT a.city IS NULL AND (o.salary IS NULL OR o.salary >= 50000) AND o.job_title IS NOT NULL AND p.record_id IN (SELECT record_id FROM watchlist) AND p.record_id NOT IN (SELECT person_id FROM ban) AND EXISTS (SELECT 1 FROM login WHERE login.person_id = p.record_id) AND NOT EXISTS (SELECT 1 FROM ban WHERE ban.person_id = p.record_id) AND o.salary > ALL (SELECT min_salary FROM pay_band) AND o.salary >= ANY (SELECT mid_salary FROM pay_band) AND p.age < SOME (SELECT max_age FROM age_limit) AND o.salary = ALL (SELECT min_salary FROM pay_band) AND o.salary <> ANY (SELECT mid_salary FROM pay_band) AND p.age <= SOME (SELECT max_age FROM age_limit) GROUP BY p.record_id, ROLLUP (p.first_name, p.last_name), CUBE (p.age), GROUPING SETS ((p.eye_color), ()), p.first_name, p.last_name, p.age, p.eye_color, p.email, p.phone_number, public.person.status, a.city, a.province, a.country, a.postal_code, o.department, o.salary, o.job_title HAVING count(*) != 0 AND NOT p.age IS NOT NULL UNION ALL SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE p.status = 'alumni' INTERSECT SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE p.record_id IN (SELECT person_id FROM alumni) EXCEPT SELECT p.record_id, p.first_name, p.last_name FROM public.person AS p WHERE EXISTS (SELECT 1 FROM suppress WHERE suppress.person_id = p.record_id) WINDOW w AS (PARTITION BY p.age ORDER BY p.record_id), w2 AS (w ROWS UNBOUNDED PRECEDING) ORDER BY p.last_name DESC NULLS LAST, p.first_name ASC NULLS FIRST, p.record_id OFFSET 5 ROWS FETCH FIRST 10 PERCENT ROWS WITH TIES FOR SHARE OF p;
